window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-596c2d60b448d3d6"]={"versions": [{"id": "FIG-596c2d60b448d3d6", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der Metamodell-Basishierarchie des AUTOSAR-Standards (Generic Structure Template). Es spezifiziert die Vererbungshierarchie der zentralen abstrakten Basisklassen <code>Referrable</code>, <code>MultilanguageReferrable</code> und <code>Identifiable</code> sowie deren Aggregationen bzw. Kompositionen zu Dokumentations- und Metadaten-Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Referrable</strong> (abstrakt): Oberste Basisklasse mit Attribut <code>+ shortName :Identifier</code>.\n</li><li><strong>MultilanguageReferrable</strong> (abstrakt): Spezialisierung von <code>Referrable</code>, aggregiert per gerichteter Komposition <code>+longName</code> mit Kardinalität <code>0..1</code> die Klasse <code>MultilanguageLongName</code>.\n</li><li><strong>Identifiable</strong> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code>. Besitzt die Attribute <code>+ category :CategoryString [0..1]</code> und <code>+ uuid :String [0..1]</code>. Komponiert folgende Elemente:\n<ul class=\"fig-list\"><li><code>+desc</code> mit Kardinalität <code>0..1</code> vom Typ <code>MultiLanguageOverviewParagraph</code>\n</li><li><code>+adminData</code> mit Kardinalität <code>0..1</code> vom Typ <code>AdminData</code> (mit Attribut <code>+ language :LEnum [0..1]</code>)\n</li><li><code>+introduction</code> mit Kardinalität <code>0..1</code> vom Typ <code>«atpMixed» DocumentationBlock</code>\n</li><li><code>+annotation</code> mit Kardinalität <code>0..*</code> vom Typ <code>Annotation</code> (mit Stereotyp/Spezialisierungsangabe <code>GeneralAnnotation</code>)\n</li></ul>\n</li><li><strong>Kommentar-Notiz (<code>xml.sequenceOffset</code>)</strong>: Definiert die Serialisierungsreihenfolge für XML: <code>desc: -60</code>, <code>category: -50</code>, <code>adminData: -40</code>, <code>introduction -30</code>, <code>annotation -25</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellarchitektur ohne Verhaltens- oder Sequenzspezifikation. Instanzen werden im Rahmen der ARXML-Modellbildung und XML-Serialisierung instantiiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der Basiseigenschaften von identifizierbaren AUTOSAR-Modellelementen. Jedes <code>Identifiable</code> erbt die globale Referenzierbarkeit über den eindeutigen <code>shortName</code> und die Mehrsprachigkeit des Namens (<code>MultilanguageLongName</code>). Die Kommentar-Notiz <code>xml.sequenceOffset</code> legt verbindlich die relative XML-Reihenfolge der Kindelemente bei der Schema-Generierung bzw. Serialisierung fest. Typen wie <code>Identifier</code>, <code>CategoryString</code> und <code>LEnum</code> unterliegen AUTOSAR-spezifischen Wertebereichseinschränkungen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-01baede55584240d", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der Metamodell-Basishierarchie des AUTOSAR-Standards (Generic Structure Template). Es spezifiziert die Vererbungshierarchie der zentralen abstrakten Basisklassen <code>Referrable</code>, <code>MultilanguageReferrable</code> und <code>Identifiable</code> sowie deren Aggregationen bzw. Kompositionen zu Dokumentations- und Metadaten-Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Referrable</strong> (abstrakt): Oberste Basisklasse mit Attribut <code>+ shortName: Identifier</code>.\n</li><li><strong>MultilanguageReferrable</strong> (abstrakt): Spezialisierung von <code>Referrable</code>, aggregiert per gerichteter Komposition <code>+longName</code> mit Kardinalität <code>0..1</code> die Klasse <code>MultilanguageLongName</code>.\n</li><li><strong>Identifiable</strong> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code>. Besitzt die Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>. Komponiert folgende Elemente:\n<ul class=\"fig-list\"><li><code>+desc</code> mit Kardinalität <code>0..1</code> vom Typ <code>MultiLanguageOverviewParagraph</code>\n</li><li><code>+adminData</code> mit Kardinalität <code>0..1</code> vom Typ <code>AdminData</code> (mit Attribut <code>+ language: LEnum [0..1]</code>)\n</li><li><code>+introduction</code> mit Kardinalität <code>0..1</code> vom Typ <code>«atpMixed» DocumentationBlock</code>\n</li><li><code>+annotation</code> mit Kardinalität <code>0..*</code> vom Typ <code>Annotation</code> (mit Stereotyp/Spezialisierungsangabe <code>GeneralAnnotation</code>)\n</li></ul>\n</li><li><strong>Kommentar-Notiz (<code>xml.sequenceOffset</code>)</strong>: Definiert die Serialisierungsreihenfolge für XML: <code>desc: -60</code>, <code>category: -50</code>, <code>adminData: -40</code>, <code>introduction -30</code>, <code>annotation -25</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellarchitektur ohne Verhaltens- oder Sequenzspezifikation. Instanzen werden im Rahmen der ARXML-Modellbildung und XML-Serialisierung instantiiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der Basiseigenschaften von identifizierbaren AUTOSAR-Modellelementen. Jedes <code>Identifiable</code> erbt die globale Referenzierbarkeit über den eindeutigen <code>shortName</code> und die Mehrsprachigkeit des Namens (<code>MultilanguageLongName</code>). Die Kommentar-Notiz <code>xml.sequenceOffset</code> legt verbindlich die relative XML-Reihenfolge der Kindelemente bei der Schema-Generierung bzw. Serialisierung fest. Typen wie <code>Identifier</code>, <code>CategoryString</code> und <code>LEnum</code> unterliegen AUTOSAR-spezifischen Wertebereichseinschränkungen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-94e80ab0b20838b5", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der Metamodell-Basishierarchie des AUTOSAR-Standards (Generic Structure Template). Es spezifiziert die Vererbungshierarchie der zentralen abstrakten Basisklassen <code>Referrable</code>, <code>MultilanguageReferrable</code> und <code>Identifiable</code> sowie deren Aggregationen bzw. Kompositionen zu Dokumentations- und Metadaten-Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Referrable</strong> (abstrakt): Oberste Basisklasse mit Attribut <code>«atpIdentityContributor» + shortName: Identifier</code>.\n</li><li><strong>MultilanguageReferrable</strong> (abstrakt): Spezialisierung von <code>Referrable</code>, aggregiert per gerichteter Komposition <code>+longName</code> mit Kardinalität <code>0..1</code> die Klasse <code>MultilanguageLongName</code>.\n</li><li><strong>Identifiable</strong> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code>. Besitzt die Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>. Komponiert folgende Elemente:\n<ul class=\"fig-list\"><li><code>+desc</code> mit Kardinalität <code>0..1</code> vom Typ <code>MultiLanguageOverviewParagraph</code>\n</li><li><code>+adminData</code> mit Kardinalität <code>0..1</code> vom Typ <code>AdminData</code> (mit Attribut <code>+ language: LEnum [0..1]</code>)\n</li><li><code>+introduction</code> mit Kardinalität <code>0..1</code> vom Typ <code>«atpMixed» DocumentationBlock</code>\n</li><li><code>+annotation</code> mit Kardinalität <code>0..*</code> vom Typ <code>Annotation</code> (mit Stereotyp/Spezialisierungsangabe <code>GeneralAnnotation</code>)\n</li></ul>\n</li><li><strong>Kommentar-Notiz (<code>xml.sequenceOffset</code>)</strong>: Definiert die Serialisierungsreihenfolge für XML: <code>desc: -60</code>, <code>category: -50</code>, <code>adminData: -40</code>, <code>introduction -30</code>, <code>annotation -25</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellarchitektur ohne Verhaltens- oder Sequenzspezifikation. Instanzen werden im Rahmen der ARXML-Modellbildung und XML-Serialisierung instantiiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der Basiseigenschaften von identifizierbaren AUTOSAR-Modellelementen. Jedes <code>Identifiable</code> erbt die globale Referenzierbarkeit über <code>shortName</code>, welcher explizit mit dem Stereotyp <code>«atpIdentityContributor»</code> annotiert ist und somit zwingend zur Identitätsbildung und Pfadreferenzierung des Modellelements im AUTOSAR-Metamodell beiträgt, sowie die Mehrsprachigkeit des Namens (<code>MultilanguageLongName</code>). Die Kommentar-Notiz <code>xml.sequenceOffset</code> legt verbindlich die relative XML-Reihenfolge der Kindelemente bei der Schema-Generierung bzw. Serialisierung fest. Typen wie <code>Identifier</code>, <code>CategoryString</code> und <code>LEnum</code> unterliegen AUTOSAR-spezifischen Wertebereichseinschränkungen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ee27a57981d78dda", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der Metamodell-Basishierarchie des AUTOSAR-Standards (Generic Structure Template). Es spezifiziert die Vererbungshierarchie der zentralen abstrakten Basisklassen <code>Referrable</code>, <code>MultilanguageReferrable</code> und <code>Identifiable</code> sowie deren Aggregationen bzw. Kompositionen zu Dokumentations- und Metadaten-Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Referrable</strong> (abstrakt): Oberste Basisklasse mit Attribut <code>«atpIdentityContributor» + shortName: Identifier</code>.\n</li><li><strong>MultilanguageReferrable</strong> (abstrakt): Spezialisierung von <code>Referrable</code>, aggregiert per gerichteter Komposition <code>+longName</code> mit Kardinalität <code>0..1</code> die Klasse <code>MultilanguageLongName</code>.\n</li><li><strong>Identifiable</strong> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code>. Besitzt die Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>. Komponiert folgende Elemente:\n<ul class=\"fig-list\"><li><code>+desc</code> mit Kardinalität <code>0..1</code> vom Typ <code>MultiLanguageOverviewParagraph</code>\n</li><li><code>+adminData</code> mit Kardinalität <code>0..1</code> vom Typ <code>AdminData</code> (mit Attribut <code>+ language: LEnum [0..1]</code>), ausgezeichnet mit dem Stereotyp <code>«atpSplitable»</code>\n</li><li><code>+introduction</code> mit Kardinalität <code>0..1</code> vom Typ <code>«atpMixed» DocumentationBlock</code>\n</li><li><code>+annotation</code> mit Kardinalität <code>0..*</code> vom Typ <code>Annotation</code> (mit Stereotyp/Spezialisierungsangabe <code>GeneralAnnotation</code>)\n</li></ul>\n</li><li><strong>Kommentar-Notiz (<code>xml.sequenceOffset</code>)</strong>: Definiert die Serialisierungsreihenfolge für XML: <code>desc: -60</code>, <code>category: -50</code>, <code>adminData: -40</code>, <code>introduction -30</code>, <code>annotation -25</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellarchitektur ohne Verhaltens- oder Sequenzspezifikation. Instanzen werden im Rahmen der ARXML-Modellbildung und XML-Serialisierung instantiiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der Basiseigenschaften von identifizierbaren AUTOSAR-Modellelementen. Jedes <code>Identifiable</code> erbt die globale Referenzierbarkeit über <code>shortName</code>, welcher explizit mit dem Stereotyp <code>«atpIdentityContributor»</code> annotiert ist und somit zwingend zur Identitätsbildung und Pfadreferenzierung des Modellelements im AUTOSAR-Metamodell beiträgt, sowie die Mehrsprachigkeit des Namens (<code>MultilanguageLongName</code>). Die Assoziation <code>+adminData</code> ist mit <code>«atpSplitable»</code> gekennzeichnet, womit administrative Daten über mehrere physische ARXML-Dateien/Fragmente hinweg aufgeteilt (gesplittet) werden dürfen. Die Kommentar-Notiz <code>xml.sequenceOffset</code> legt verbindlich die relative XML-Reihenfolge der Kindelemente bei der Schema-Generierung bzw. Serialisierung fest. Typen wie <code>Identifier</code>, <code>CategoryString</code> und <code>LEnum</code> unterliegen AUTOSAR-spezifischen Wertebereichseinschränkungen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2b227e4d683fd230", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der Metamodell-Basishierarchie des AUTOSAR-Standards (Generic Structure Template). Es spezifiziert die Vererbungshierarchie der zentralen abstrakten Basisklassen <code>Referrable</code>, <code>MultilanguageReferrable</code> und <code>Identifiable</code> sowie deren Aggregationen bzw. Kompositionen zu Dokumentations- und Metadaten-Elementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Referrable</strong> (abstrakt): Oberste Basisklasse mit Attribut <code>«atpIdentityContributor» + shortName: Identifier</code>.\n</li><li><strong>MultilanguageReferrable</strong> (abstrakt): Spezialisierung von <code>Referrable</code>, aggregiert per gerichteter Komposition <code>+longName</code> mit Kardinalität <code>0..1</code> die Klasse <code>MultilanguageLongName</code>.\n</li><li><strong>Identifiable</strong> (abstrakt): Spezialisierung von <code>MultilanguageReferrable</code>. Besitzt die Attribute <code>+ category: CategoryString [0..1]</code> und <code>+ uuid: String [0..1]</code>. Komponiert folgende Elemente:\n<ul class=\"fig-list\"><li><code>+desc</code> mit Kardinalität <code>0..1</code> vom Typ <code>MultiLanguageOverviewParagraph</code>\n</li><li><code>+adminData</code> mit Kardinalität <code>0..1</code> vom Typ <code>AdminData</code> (mit Attribut <code>+ language: LEnum [0..1]</code>), ausgezeichnet mit dem Stereotyp <code>«atpSplitable»</code>\n</li><li><code>+introduction</code> mit Kardinalität <code>0..1</code> vom Typ <code>«atpMixed» DocumentationBlock</code>\n</li><li><code>+annotation</code> mit Kardinalität <code>0..*</code> vom Typ <code>Annotation</code> (mit Stereotyp/Spezialisierungsangabe <code>GeneralAnnotation</code>)\n</li></ul>\n</li><li><strong>Kommentar-Notiz (<code>xml.sequenceOffset</code>)</strong>: Definiert die Serialisierungsreihenfolge für XML: <code>desc: -60</code>, <code>category: -50</code>, <code>adminData: -40</code>, <code>introduction -30</code>, <code>annotation -25</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodellarchitektur ohne Verhaltens- oder Sequenzspezifikation. Instanzen werden im Rahmen der ARXML-Modellbildung und XML-Serialisierung instantiiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der Basiseigenschaften von identifizierbaren AUTOSAR-Modellelementen. Jedes <code>Identifiable</code> erbt die globale Referenzierbarkeit über <code>shortName</code>, welcher explizit mit dem Stereotyp <code>«atpIdentityContributor»</code> annotiert ist und somit zwingend zur Identitätsbildung und Pfadreferenzierung des Modellelements im AUTOSAR-Metamodell beiträgt, sowie die Mehrsprachigkeit des Namens (<code>MultilanguageLongName</code>). Die Assoziation <code>+adminData</code> ist mit <code>«atpSplitable»</code> gekennzeichnet, womit administrative Daten über mehrere physische ARXML-Dateien/Fragmente hinweg aufgeteilt (gesplittet) werden dürfen. Die Kommentar-Notiz <code>xml.sequenceOffset</code> legt verbindlich die relative XML-Reihenfolge der Kindelemente bei der Schema-Generierung bzw. Serialisierung fest. Typen wie <code>Identifier</code>, <code>CategoryString</code> und <code>LEnum</code> unterliegen AUTOSAR-spezifischen Wertebereichseinschränkungen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-596c2d60b448d3d6", "to": "FIG-01baede55584240d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Typografische Bereinigung bei Attributdeklarationen: Bei <code>shortName: Identifier</code> (in <code>Referrable</code>), <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code> (in <code>Identifiable</code>) sowie <code>language: LEnum [0..1]</code> (in <code>AdminData</code>) wurde das Leerzeichen vor dem Doppelpunkt entfernt.\n</li><li>Bereinigung der Rollenbezeichnung an der Assoziation zwischen <code>MultilanguageReferrable</code> und <code>MultilanguageLongName</code>: Positionierung und Formatierung von <code>+longName</code> über der Assoziationslinie standardisiert.\n</li></ul>"}, {"from": "FIG-01baede55584240d", "to": "FIG-94e80ab0b20838b5", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klasse <code>Referrable</code>: Dem Attribut <code>shortName</code> wurde der AUTOSAR-Stereotyp <code>«atpIdentityContributor»</code> vorangestellt.\n</li></ul>"}, {"from": "FIG-94e80ab0b20838b5", "to": "FIG-ee27a57981d78dda", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Assoziation <code>adminData</code> (zwischen <code>Identifiable</code> und <code>AdminData</code>): Ergänzung des AUTOSAR-Stereotyps <code>«atpSplitable»</code> an der Beziehung.\n</li></ul>"}, {"from": "FIG-ee27a57981d78dda", "to": "FIG-2b227e4d683fd230", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
